import os

from error_list import error_messages


def infer_error_type(msg: str) -> str:
    return (
        msg.replace("'", "")
        .replace("/", " ")
        .replace("(", " ")
        .replace(")", " ")
        .title()
        .replace(" ", "")
    )


header = """/// WARNING: This code was generated by python/generate_errors.py
///
/// DO NOT EDIT THIS CODE!!!
///
/// Instead, make changes to python/generate_errors.py and python/error_list.py
/// and run the script to regenerate this code like this:
///
/// cd python
/// python3 generate_errors.py
///

use std::collections::HashMap;

#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash)]
pub enum ErrorType {
"""


def workflow():
    output_path = os.path.join("..", "src", "errors.rs")

    prog = ""
    prog += header

    for msg in error_messages:
        prog += f"    {infer_error_type(msg)},\n"

    prog += """}

#[derive(Debug, Clone)]
pub struct ErrorStatus {
    pub error_type: ErrorType,
    pub line_number: usize,
    pub statement_number: usize,
    pub token_sequence: usize,
}

pub fn get_error_map() -> HashMap<ErrorType, String> {
    return HashMap::from([
"""

    map_data = ""
    for msg in error_messages:
        error_type = infer_error_type(msg)
        map_data += f'        (ErrorType::{error_type}, String::from("{msg}")),\n'

    prog += map_data
    prog += """    ])
}
"""

    prog += """pub fn is_warning(error_type: ErrorType) -> bool {
    match error_type {
        ErrorType::NamedFileAlreadyExists => true,
        ErrorType::ExcessInputDataIgnored => true,
        ErrorType::VariableWithoutAnyValue => true,
        _ => false
    }
}
"""

    with open(output_path, "w") as f:
        f.write(prog)


if __name__ == "__main__":
    workflow()
